void pagevec_unlock(struct pagevec *pvec, struct zone *zone) {
    int i;
    int unlocked_count = 0;

    for (i = 0; i < pvec->nr_pages; i++) {
        struct page *page = pvec->pages[i];

        if (PageLocked(page)) {
            unlock_page(page);
            unlocked_count++;
        }
    }

    for (i = 0; i < pvec->nr_pages; i++) {
        struct page *page = pvec->pages[i];

        if (!PageLocked(page)) {
            put_page(page);
        }
    }

    for (i = 0; i < unlocked_count; i++) {
        struct page *page = pvec->pages[i];

        if (PageLRU(page)) {
            putback_lru_page(page, zone);
        }
    }
}
